	[ 'eans' => [ '5714241013051' ], 'html' => '<p>Nedre kabeltræk (dobbelt) fra UpForm er en kabelstation med to trækpunkter nede ved gulvet.</p>' ],
	[ 'eans' => [ '5714241012436' ], 'html' => '<p>Triceps-maskine UR-U035 fra UpForm er udviklet til målrettet og isoleret træning af triceps.</p>' ],
	[ 'eans' => [ '5714605002790' ], 'html' => '<p>Relax Crossover Pulley Combo PTT0112 er en cable cross-maskine med to vægtmagasiner på hver 109 kg. Maskinen er en fast del af mange fitnesscentre og giver et bredt udvalg af kabeløvelser.</p>' ],
	[ 'eans' => [ '5714241012726' ], 'html' => '<p>Pullup- og dipstationen fra UpForm giver dig to klassiske kropsvægtøvelser i samme station.</p>' ],
	[ 'eans' => [ '5714241012542' ], 'html' => '<p>Smith-maskine UR-U002 fra UpForm er en løsning til kontrolleret styrketræning i fitnesscentre.</p>' ],
	[ 'eans' => [ '8717842032527' ], 'html' => '<p>Tunturi T90 Signature er et løbebånd med 5 HK AC-motor og hastighed op til 24 km/t. Dæmpningen hedder T-Flex Comfort+, og løbefladen er stor. Der er 47 programmer, blandt dem HRC og brugertilpassede, og båndet kobles via Bluetooth til Zwift, Kinomap og andre apps.</p>' ],
	[ 'eans' => [ '8029975805238' ], 'html' => '<p>Toorx Mirage S80 TFT har en touchskærm, der gør betjeningen overskuelig, og viser dine træningsdata. Motoren er en 4,5 HK AC-motor med hastighed op til 22 km/t, og løbefladen måler 57 x 160 cm. Bluetooth gør båndet klar til Zwift, Kinomap og iConsole+.</p>' ],
	[ 'eans' => [ '7051943748668' ], 'html' => '<p>Keiser M3i Studio Plus er en spinningcykel til professionelt brug med Studio Display og Coach by Color. Du kan vælge mellem 72 modstandsniveauer, og cyklen understøtter Bluetooth, ANT+ og populære træningsapps.</p>' ],
	[ 'eans' => [ '5714237009129' ], 'html' => '<p>Odin PRO Seated Leg Press 150 kg er en siddende benpresmaskine til kommercielle fitnesscentre og motionsrum. Leg press er en af de øvelser, mange vælger først i centret, og maskinen er enkel at bruge.</p>' ],
	[ 'eans' => [ '5714241012702' ], 'html' => '<p>Benpresmaskinen fra UpForm er en maskine til fitnesscentre, der træner benene.</p>' ],
	[ 'eans' => [ '5714241012719' ], 'html' => '<p>Bryst- og skuldermaskinen fra UpForm samler træning af bryst og skuldre i samme maskine.</p>' ],
	[ 'eans' => [ '5714241013242', '5714241013273', '5714241012962' ], 'html' => '<p>Lat Pulldown UF-020 fra UpForm er en trækstation til ryggen, hvor du trækker stangen ned mod brystet.</p>' ],
	[ 'eans' => [ '5714241012696' ], 'html' => '<p>Leg Curl-maskinen fra UpForm har et vægtstakssystem og er lavet til fitnesscentre.</p>' ],
	[ 'eans' => [ '5714241012689' ], 'html' => '<p>Skulderpresmaskinen UF-024 fra UpForm er designet til målrettet træning af skulderpartiet.</p>' ],
	[ 'eans' => [ '7051943738652' ], 'html' => '<p>Keiser M5i Strider er en kompakt crosstrainer med magnetisk modstand i 24 niveauer og Bluetooth. Den er udviklet til brug i hjemmet, i virksomheder og i træningscentre.</p>' ],
	[ 'eans' => [ '5714241013211' ], 'html' => '<p>Curlpull Dual Pulley Low fra UpForm er en kabelstation med dobbelte trisser i lav position.</p>' ],
	[ 'eans' => [ '5714241013075' ], 'html' => '<p>Latpull Dual Pulley High fra UpForm er en kabelstation med dobbelte trisser i høj position, fx til nedtræk.</p>' ],
	[ 'eans' => [ '8029975805863' ], 'html' => '<p>Toorx ASX-4000 er en multimaskine med 3-i-1-design, så du kan variere træningen på tværs af flere muskelgrupper. Konstruktionen er kompakt og pladsbesparende, og den er professionelt certificeret.</p>' ],
	[ 'eans' => [ '5714237009235' ], 'html' => '<p>Odin PRO Leg Press/Calf Extension er en benpresmaskine, der er mindre end den klassiske udgave. Derfor passer den til mindre motionsrum, hvor pladsen er begrænset. Vægtmagasinet er på 132 kg, og maskinen kan også bruges til lægtræning.</p>' ],
	[ 'eans' => [ '8717842037676' ], 'html' => '<p>Tunturi Platinum RW30 er en vandroeromaskine med patenteret Twin Tank og ti modstandsniveauer. Bluetooth-monitoren viser en power graph og kan bruges sammen med apps. Håndtaget er ergonomisk, og sædet er blødt.</p>' ],
	[ 'eans' => [ '5714237009242' ], 'html' => '<p>Odin PRO Crossover Pulley Combo 180 kg er en cable cross-maskine til kommercielle fitnesscentre og motionsrum. Den hører til de mest brugte maskiner i et center, og den passer til både medlemmer og trænere.</p>' ],
	[ 'eans' => [ '8029975811017' ], 'html' => '<p>Toorx Mirage C90-TFT er et løbebånd med 15,6 tommer HD-touchskærm med streamingapps og Zwift-kompatibilitet. Motoren er en 4 HK brushless-motor med op til 22 km/t. Det hydrauliske foldesystem gør, at båndet kun fylder 29 cm sammenfoldet.</p>' ],
	[ 'eans' => [ '8029975805009' ], 'html' => '<p>Toorx Mirage S80 er et løbebånd med brushless-motor og hastighed op til 20 km/t. Den store løbeflade har 15 % elektronisk stigning, og det hydrauliske foldesystem gør båndet nemt at stille væk.</p>' ],
	[ 'eans' => [ '5714605003438' ], 'html' => '<p>Relax PK 17 er et løbebånd med automatisk smøring. Det er tænkt til mindre fitnesscentre og motionsrum i firmaer.</p>' ],
	[ 'eans' => [ '5714241013006' ], 'html' => '<p>Denne 2-i-1-maskine kan bruges til både adduktor- og abduktortræning, så du slipper for to separate maskiner i centret.</p>' ],
	[ 'eans' => [ '5714241012849' ], 'html' => '<p>Professionel Leg Curl-maskine til fitnesscentre med fokus på baglåret.</p>' ],
	[ 'eans' => [ '5714241013143' ], 'html' => '<p>Denne 2-i-1 ryg- og mavetræner kombinerer to øvelser i én maskine og sparer plads i et center.</p>' ],
	[ 'eans' => [ '5714237018725' ], 'html' => '<p>Odin T970 er et motoriseret løbebånd med 21,5 tommer TFT-skærm i høj opløsning. DC-motoren er oplyst til 5,0 HK, og hastigheden kan indstilles fra 1 til 22 km/t. Der er elektronisk stigning.</p>' ],
	[ 'eans' => [ '8717842036334' ], 'html' => '<p>Tunturi Platinum CT20 er en crosstrainer med ledskånende bevægelse. Den har 48 modstandsniveauer og 400 W, så belastningen kan skrues op. Skærmen er en 7-tommers LCD-skærm med app-kompatibilitet.</p>' ],
	[ 'eans' => [ '5704796050205' ], 'html' => '<p>Active Sports Gear Pro Runner 9.0 har 4,5 HK AC-motor og hastighed op til 22 km/t. Stigningen er automatisk op til 15 %, og løbefladen er 150 x 56 cm. På den 21,5 tommer store skærm kan du spejle din mobil trådløst, og du kan oplade den undervejs.</p>' ],
	[ 'eans' => [ '8029975999999' ], 'html' => '<p>Toorx Mirage S70 er et løbebånd med brushless-motor, der giver hastighed op til 22 km/t. Løbefladen er stor med 15 % elektronisk stigning, og båndet foldes hydraulisk. Bluetooth giver adgang til Zwift, Kinomap og iConsole+.</p>' ],
	[ 'eans' => [ '8029975998114' ], 'html' => '<p>Toorx Double Cross er et kabeltræk til vægmontering, der kun er 16,5 cm dybt. Der er to vægtmagasiner på 50 kg hver, og aluminiumshjul giver en glidende og stabil bevægelse.</p>' ],
	[ 'eans' => [ '7051944094856' ], 'html' => '<p>Sole Fitness F80 ENT er et løbebånd med 10,1 tommer touchskærm, wifi og entertainment-funktioner. Motoren er på 3,5 HK, og du kan vælge mellem op til 15 stigningsniveauer og 12 brugerdefinerede programmer. Appen hedder SOLE+.</p>' ],
	[ 'eans' => [ '7051944105606' ], 'html' => '<p>Spirit CE800+ er en selvgenererende crosstrainer med 50,8 cm skridtlængde og 40 modstandsniveauer. Bluetooth FTMS giver app-tilslutning. Den er lavet til virksomheder og træningscentre.</p>' ],
	[ 'eans' => [ '5714237010705' ], 'html' => '<p>Odin PRO B1200 er en motionscykel med kraftig rammekonstruktion, der gør den slidstærk. Den er velegnet til brug i centre og til professionelle.</p>' ],
	[ 'eans' => [ '5714605005753' ], 'html' => '<p>Peak Fitness E10 Pro er en ellipsetræner til både hjemmebrug og fitnesscentre. Modstanden er elektromagnetisk, skridtlængden er 61 cm, og computeren har en 40 cm touchskærm.</p>' ],
	[ 'eans' => [ '5714237009136' ], 'html' => '<p>Odin PRO Lat Pulldown 77 kg er en kraftig og stabil nedtrækstation til fitnesscentre. Tårnet giver dig mulighed for at træne både ryg og skuldre, og vægtmagasinet er på 77 kg.</p>' ],
	[ 'eans' => [ '5714237019630' ], 'html' => '<p>Odin Pro Leg Extension og Lying Leg Curl er en 2-i-1 benmaskine: siddende benstræk til forlåret og liggende curl til baglåret. Maskinen bruger 50 mm vægtskiver.</p>' ],
	[ 'eans' => [ '5714241012900' ], 'html' => '<p>Den assisterede pull-up- og dipstation hjælper dig med at løfte kropsvægten i begge øvelser, så du kan træne dem, selv om du ikke endnu kan klare hele din vægt.</p>' ],
	[ 'eans' => [ '5714605003278' ], 'html' => '<p>Relax Lat Pull / Seated Row PC2032 er en kombimaskine til rygtræning. Den passer i et motionsrum uden meget plads, da to øvelser er samlet i én maskine.</p>' ],
	[ 'eans' => [ '5714605002899' ], 'html' => '<p>Relax Smith-stativ PTT0222 har kontravægt, så stangen kun vejer 2 kg. Rammen er i kraftigt stål og kombinerer oval og firkantet konstruktion.</p>' ],
	[ 'eans' => [ '5714605006057' ], 'html' => '<p>Peak Fitness HG8800 er en komplet træningsstation til hele kroppen med integreret vægtmagasin på 90 kg. Den tilkoblede leg press bruger samme magasin, så benene trænes uden løse vægtskiver.</p>' ],
	[ 'eans' => [ '5714237009563' ], 'html' => '<p>Odin PRO PL Lat Pulldown er en plate loaded nedtrækstation til fitnesscentre og motionsrum. Du læsser selv vægtskiver på, og puderne leveres i sort men kan bestilles i andre farver.</p>' ],
	[ 'eans' => [ '5714237009587' ], 'html' => '<p>Odin PRO PL Leg Press er en plate loaded benpres til fitnesscentre og motionsrum. Vægtskiverne lægger du selv på, og puderne er sorte, men kan bestilles i andre farver.</p>' ],
	[ 'eans' => [ '5714241012795' ], 'html' => '<p>Butterfly-maskine til fitnesscentre, der træner overkroppen i en guidet bevægelse.</p>' ],
	[ 'eans' => [ '5714241012870' ], 'html' => '<p>Mavetrænermaskine til fitnesscentre, der træner mavemusklerne.</p>' ],
	[ 'eans' => [ '5714241012856' ], 'html' => '<p>Professionel bænkpresmaskine til træning af overkroppen i et fitnesscenter.</p>' ],
	[ 'eans' => [ '5714241012832' ], 'html' => '<p>Skuldertræner MP-U228 er udviklet til målrettet og sikker træning af skuldrene.</p>' ],
	[ 'eans' => [ '5714237003851' ], 'html' => '<p>Dette pakketilbud fra Odin består af 15 sæt hex-håndvægte plus rack og vejer 545 kg samlet. Vægtene spænder fra 2 kg til 35 kg, så sættet kan bruges af både nybegyndere og øvede. Racket holder orden på vægtene og fylder ikke meget.</p>' ],
	[ 'eans' => [ '5714237019647' ], 'html' => '<p>Odin Pro Dødløft Træningsmaskine er en styrkemaskine til ben, baller, baglår og ryg. Den kombinerer en guidet løftebevægelse med flere ergonomiske grebspositioner og et vægtskivebelastet system.</p>' ],
	[ 'eans' => [ '5714241012207' ], 'html' => '<p>Smith-maskine med træningsbænk fra Gorilla Sports leveres som skaffevare med ca.Pakken giver dig et styrkeområde med både Smith-maskine og bænk.</p>' ],
	[ 'eans' => [ '5714237009426' ], 'html' => '<p>Odin PRO Smith Rack er et Smith-stativ til kommercielle fitnesscentre og motionsrum. Rammen er kraftig og stabil, og stativet er enkelt at bruge.</p>' ],
	[ 'eans' => [ '5714241012498' ], 'html' => '<p>Squat-maskine US-U003 fra UpForm er udviklet til målrettet træning af underkroppen.</p>' ],
	[ 'eans' => [ '5714237014352' ], 'html' => '<p>Odin PRO Cable Cross Elite er en kabeltrækstation til hjemmetræning med dobbelte vægtstakke på 2 x 95 kg. Den giver mange muligheder for øvelser med kabler.</p>' ],
	[ 'eans' => [ '8029975999982' ], 'html' => '<p>Toorx Mirage S60 er et løbebånd med hastighed op til 22 km/t og 15 % elektronisk stigning. Løbefladen er 153 x 54 cm med otte affjedringszoner. Der er 24 programmer, HRC-funktioner og en body-fat-måling.</p>' ],
	[ 'eans' => [ '5714241012474' ], 'html' => '<p>Ben Curl-maskinen fra UpForm er designet til træning af baglårene.</p>' ],
	[ 'eans' => [ '5714241013181' ], 'html' => '<p>Leg Extension-maskinen fra UpForm har justerbart sæde og ryglæn, så den passer til brugere i forskellig højde.</p>' ],
	[ 'eans' => [ '5714241012399' ], 'html' => '<p>Ryg- og skuldermaskine US-U005 fra UpForm samler overkropstræning i én maskine.</p>' ],
	[ 'eans' => [ '5714241012405' ], 'html' => '<p>Skuldermaskine US-U002 fra UpForm er udviklet til effektiv og kontrolleret skuldertræning.</p>' ],
	[ 'eans' => [ '8029975995656' ], 'html' => '<p>Toorx MSX3000 er en multistation med 90 kg vægtstak og kabelbaseret træning til næsten alle muskelgrupper. Konstruktionen er solid og har et fuldt beskyttelsesbur.</p>' ],
	[ 'eans' => [ '7051943748255' ], 'html' => '<p>Abilica Premium Mill 90 er et løbebånd med 2,0 HK AC-motor og hastighed op til 22 km/t. Løbefladen er 56 x 155 cm, og båndet kan kobles til AnyRun, Zwift og Kinomap. Det passer både til hjemmet og til virksomheder.</p>' ],
	[ 'eans' => [ '5714605003414' ], 'html' => '<p>Relax 45 Degree Leg Press PTT0116 er en benpres med 45 graders vinkel. Maskinen er biomekanisk funktionel og lavet til professionelt brug.</p>' ],
	[ 'eans' => [ '5714237009198' ], 'html' => '<p>Odin PRO Lat Pulldown/Seated Row er to træningsstationer i én maskine: et klassisk træktårn og en siddende low row. Vægtmagasinet er på 77 kg.</p>' ],
	[ 'eans' => [ '5714241012481' ], 'html' => '<p>AB Crunch fra UpForm er en mavemaskine med præcis vægtjustering.</p>' ],
	[ 'eans' => [ '5714241013129' ], 'html' => '<p>Det højdejusterbare kabeltræk fra UpForm lader dig flytte trækpunktet op og ned for at tilpasse øvelsen.</p>' ],
	[ 'eans' => [ '5714241013013' ], 'html' => '<p>UpForms tricepsmaskine er designet til isoleret tricepstræning.</p>' ],
	[ 'eans' => [ '5714605005401' ], 'html' => '<p>Drax Fit+ Curve Running er et buet løbebånd uden motor og uden behov for strøm. Du bestemmer selv hastigheden, og bevægelsen giver en fornemmelse af at løbe udendørs. Dette eksemplar er brugt.</p>' ],
	[ 'eans' => [ '5714237015298' ], 'html' => '<p>Odin Elite Half Rack er et styrkestativ med kraftige profiler, indbygget chin-up bar og vægtopbevaring. Det er bygget til hård kommerciel brug.</p>' ],
	[ 'eans' => [ '8029975999562' ], 'html' => '<p>Toorx BRX-9500 er en motionscykel med selvforsynende energikilde, så den ikke skal sluttes til strøm. Der er 32 digitale modstandsniveauer og en LED-konsol med træningsdata. Cyklen kan justeres ergonomisk.</p>' ],
	[ 'eans' => [ '8029975811000' ], 'html' => '<p>Toorx Mirage C90 har 4 HK brushless-motor og hastighed op til 22 km/t. Løbefladen er ekstra stor med 15 % stigning, og det hydrauliske foldesystem gør båndet nemt at stille væk.</p>' ],
	[ 'eans' => [ '8029975999968' ], 'html' => '<p>Toorx Mirage S40 er et løbebånd med hastighed op til 22 km/t og 15 % elektronisk stigning. Løbefladen er 51 x 148 cm med otte affjedringszoner. Du får 24 programmer, HRC og body-fat-måling.</p>' ],
	[ 'eans' => [ '5714605004176' ], 'html' => '<p>Peak Fitness C10 er en crosstrainer med wifi og 10 tommer stor skærm. Skridtlængden justeres elektronisk, direkte fra din position på maskinen. Den kan bruges af hele familien eller på arbejdspladsen.</p>' ],
	[ 'eans' => [ '5714237018893' ], 'html' => '<p>Sensol Smart Pilates Reformer RS3 har op til 45 kg motoriseret modstand, som kan justeres i intervaller på 1 kg. Der er tre modstandstilstande, og modellen har kraftigere digital modstand end RS2-serien.</p>' ],
	[ 'eans' => [ '8717842037041' ], 'html' => '<p>Tunturi Signature R90W er en vandroeromaskine med patenteret Twin Tank og fem modstandsniveauer. Bluetooth-monitoren viser en power graph og kan bruges med apps. Håndtaget er ergonomisk, og sædet er blødt.</p>' ],
	[ 'eans' => [ '7051944127479' ], 'html' => '<p>Spirit CU800+ er en motionscykel med 40 modstandsniveauer, pulsmåling og Bluetooth. Den passer til træning derhjemme, i virksomheder og i træningsrum.</p>' ],
	[ 'eans' => [ '5714241012160' ], 'html' => '<p>Smith-maskine og komplet power rack i ét fra Gorilla Sports. Varen er skaffevare, så regn med ca.</p>' ],
	[ 'eans' => [ '70438101301361' ], 'html' => '<p>Denne pakke fra Abilica er et komplet styrketræningssæt til hjemmet med power rack, bænk og farvede bumper-vægtskiver på 170 kg.</p>' ],
	[ 'eans' => [ '5714237009259' ], 'html' => '<p>Odin PRO 45 Degree Leg Press er en benpres med 45 graders vinkel til kommercielle fitnesscentre og motionsrum. Maskinen er kraftig og stabil og træner benene.</p>' ],
	[ 'eans' => [ '5714237011672' ], 'html' => '<p>Odin Pro T1100 er et løbebånd til erhverv eller den krævende bruger. Konstruktionen er robust, og designet er stilrent.</p>' ],
	[ 'eans' => [ '8029975805399' ], 'html' => '<p>Toorx ERX-900 TFT er en crosstrainer med 16 modstandsniveauer og 10 tommer TFT-touchskærm med Kinomap og Netflix. Designet er kompakt, og transporthjul gør den let at flytte.</p>' ],
	[ 'eans' => [ '5714241013266' ], 'html' => '<p>Den skrå bænkpresmaskine er designet til målrettet træning af brystmuskulaturen, især den øvre del.</p>' ],
	[ 'eans' => [ '5743814009627' ], 'html' => '<p>American Barbell 140 kg Color Urethane Pro Series Bumper Plate-pakken er et sæt bumper-vægtskiver i farvet urethan med en samlet vægt på 140 kg.</p>' ],
	[ 'eans' => [ '0196625281389', '0196625279560' ], 'html' => '<p>Specialized Sirrus X 5.0 er en cykel til motion, pendling og længere ture på varieret underlag. Den føles let på asfalt, men har komfort nok til ujævne stræk og grusveje. Modellen er årgang 2027 i farven Gloss Warm Smoke / Sandstone Metallic.</p>' ],
	[ 'eans' => [ '70438101305261' ], 'html' => '<p>Abilica PR 550 Power Rack Bumper er et komplet rack med lat pull-down, roning og kabeltræk foran. Pakken omfatter stang, bumper-vægtskiver på 150 kg, bænk og låse.</p>' ],
	[ 'eans' => [ '5714241012573' ], 'html' => '<p>Multi Squat Rack fra UpForm er et squat rack til fitnesscentre.</p>' ],
	[ 'eans' => [ '5714237011818' ], 'html' => '<p>Odin PRO Cable Cross Elite i udgaven med to vægtstakke på 59 kg hver, 118 kg i alt. Kabeltårnet er til hjemmetræning og giver mange øvelsesmuligheder.</p>' ],
	[ 'eans' => [ '8717842032466' ], 'html' => '<p>Tunturi T60 Signature er et løbebånd med hastighed op til 20 km/t og 15 % elektronisk hældning. Løbefladen er ekstra bred med T-Flex Comfort Plus dæmpning, og Bluetooth giver forbindelse til Tunturi Routes og Zwift.</p>' ],
	[ 'eans' => [ '8029975805856' ], 'html' => '<p>Toorx ASX-3000 er en 4-i-1 multi-træningsstation med foldbar og pladsbesparende konstruktion. Stationen giver mulighed for flere typer styrketræning.</p>' ],
	[ 'eans' => [ '0885652029520' ], 'html' => '<p>Adidas T-800 er et løbebånd med High Incline: op til 40 % stigning i Climb Mode og 22 km/t i Running Mode. Motoren er en 5 HK peak brushless, og løbefladen er 152 x 52 cm. Bluetooth giver forbindelse til Zwift, Kinomap og adidas Console+.</p>' ],
	[ 'eans' => [ '8029975805382' ], 'html' => '<p>Toorx ERX-900 er en crosstrainer med 20 kg svinghjul og 16 elektroniske modstandsniveauer. Skridtlængden kan sættes til 43 eller 56 cm. Bluetooth giver forbindelse til iConsole+, Zwift og Kinomap.</p>' ],
	[ 'eans' => [ '5714605005913' ], 'html' => '<p>Peak Fitness Lat Tower Pro 3in1 er et kompakt kabeltårn med justerbart sæde og fleksible trækpunkter. Du kan bruge det som lat tower, low row og til funktionel træning.</p>' ],
	[ 'eans' => [ '5714241014751' ], 'html' => '<p>Fitnesscenter-benpresmaskine 1100 er en professionel løsning, der kombinerer benpres og hack squat. Den leveres som skaffevare med ca.</p>' ],
	[ 'eans' => [ '70438101301021' ], 'html' => '<p>Abilica PR 550 Power Rack Olympic er en komplet pakke til tung styrketræning derhjemme, med bænk og vægt på 150 kg. Racket har lat pull-down, roning og kabeltræk foran.</p>' ],
	[ 'eans' => [ '5714241015420' ], 'html' => '<p>Multistation med trækstation og pull-up er skabt til fitnesscentermiljøer. Den er skaffevare med ca.</p>' ],
	[ 'eans' => [ '5714237018671' ], 'html' => '<p>Odin T860 FjeldRun har en 3,5 HK DC-motor, hastighed op til 22 km/t og et hældningsområde fra -6 til +48 trin. Det gør det muligt at træne bakkeløb og nedløb på båndet.</p>' ],
	[ 'eans' => [ '8029975996615' ], 'html' => '<p>Toorx TRX Power Compact S har en 3,5 HK motor og topfart på 20 km/t. Stigningen er elektronisk på 15 % fordelt på 15 niveauer. Løbefladen er stor og har ti affjedringszoner.</p>' ],
	[ 'eans' => [ '0196625237690' ], 'html' => '<p>Specialized Sirrus X 5.0 2026 er topmodellen i Sirrus-serien. Cyklen har carbonramme, Compliance Junction-design og Shimano Deore 12-speed. Farven er Gloss Bordeaux Metallic.</p>' ],
	[ 'eans' => [ '0196625237249' ], 'html' => '<p>Specialized Sirrus X 5.0 2026 er topmodellen i Sirrus-serien med carbonramme, Compliance Junction-design og Shimano Deore 12-speed. Farven er Satin Photon Tint Over Liquid Silver.</p>' ],
	[ 'eans' => [ '70438101301991' ], 'html' => '<p>Abilica Half Rack med farvede bumper, bænk og nedtræk er en komplet styrkepakke. Den indeholder half rack med opbevaring af vægtskiver, justerbar bænk, lat modul, bumper-vægtskiver og vægtstang med en totalvægt på 170 kg.</p>' ],
	[ 'eans' => [ '5714237018879' ], 'html' => '<p>Sensol Smart Pilates Reformer RS2 har aluminiumsskinner, stor glideslæde og høj maksimal brugervægt. Motoren giver op til 30 kg modstand.</p>' ],
	[ 'eans' => [ '5704796045775' ], 'html' => '<p>ASG Velocity har brushless DC-motor med 2,5 HK motoreffekt og 3,75 HK peak. Hastigheden er op til 20 km/t, og stigningen er automatisk i 26 niveauer. Løbefladen er 150 x 50 cm, og maksimal brugervægt er 150 kg.</p>' ],
	[ 'eans' => [ '0885652029551' ], 'html' => '<p>Adidas X-800 Power Stride er en crosstrainer med elektronisk justerbar skridtlængde fra 46 til 58 cm og 32 elektroniske modstandsniveauer. Bluetooth giver forbindelse til Adidas Console+ og Kinomap.</p>' ],
	[ 'eans' => [ '8029975999852' ], 'html' => '<p>Toorx Mirage C60 er et smalt, sort løbebånd, der kan foldes sammen og spare plads. Motoren er på 3 HK, hastigheden op til 18 km/t og stigningen 12 %. Løbefladen har affjedringszoner.</p>' ],
	[ 'eans' => [ '8029975993072' ], 'html' => '<p>Toorx MSX 70 er en multistation med kabelsystem med kuglelejer. Den er storebror til MSX 60, og sættet indeholder triceps bar, ankelmanchetter og lateral bar.</p>' ],
	[ 'eans' => [ '5704796039187' ], 'html' => '<p>Nordic Pro 4443 er en foldbar reformer-maskine, der kun fylder 0,3 m2 ved opbevaring. Fodpedalen er justerbar, og der er seks fjedre. Finishen er sort og hvid i PU-læder og aluminium.</p>' ],
	[ 'eans' => [ '5704796039170' ], 'html' => '<p>Nordic Pro 4443 er en foldbar reformer, der fylder 0,3 m2 opbevaret. Fodpedalen er justerbar, og der er seks fjedre. Udgaven her har grå og hvid finish i PU-læder og aluminium.</p>' ],
	[ 'eans' => [ '8029975805016' ], 'html' => '<p>Toorx Voyager er et løbebånd med hastighed op til 18 km/t og 15 % elektronisk stigning. Det kan kobles til Zwift, Kinomap og iConsole+, og Soft Tech-støddæmpningen skåner leddene under løb.</p>' ],
	[ 'eans' => [ '70438101301409' ], 'html' => '<p>Abilica PR 550 Power Rack Bumper med bænk og 110 kg vægtskiver er et komplet rack med lat pull-down, roning og kabeltræk foran. Pakken omfatter stang, bumper-vægtskiver, bænk og låse.</p>' ],
	[ 'eans' => [ '5714605004732' ], 'html' => '<p>Powertec Power Rack med bumper-vægtsæt på 128 kg er en pakkeløsning. Den omfatter Powertec Power Rack Black, Powertec WB Utility Bench og Peak Fitness 128 kg bumper plates.</p>' ],
	[ 'eans' => [ '70438101301199' ], 'html' => '<p>Abilica PR 550 Power Rack Olympic med bænk og 110 kg er et komplet rack med lat pull-down, roning og kabeltræk foran. Pakken indeholder stang, olympiske vægtskiver, bænk og låse.</p>' ],
	[ 'eans' => [ '5714237018732' ], 'html' => '<p>Odin C1010 er en crosstrainer med 15,6 tommer TFT-touchskærm og 32 elektroniske modstandsniveauer. Stigningen er motorstyret op til 15 %.</p>' ],
	[ 'eans' => [ '8717842032459' ], 'html' => '<p>Tunturi T50 Signature er et løbebånd med hastighed op til 20 km/t og 15 % elektronisk hældning. Håndstøtte, sikkerhedsbøjle og Soft-Drop giver tryghed under løb.</p>' ],
	[ 'eans' => [ '4711291289369', '4711291289376', '4711291289383', '4711291289352' ], 'html' => '<p>Giant Liv BeLiv SL 0 fra 2027 har et let stel med aeroformning, der gør det lettere at træde i pedalerne. Styringen er præcis, så du har kontrol, både når du jagter tiden, og når du bare cykler ud i solen. Farven er Asphalt Green.</p>' ],
	[ 'eans' => [ '4711291289604', '4711291289611' ], 'html' => '<p>Giant Liv BeLiv SL 1 fra 2027 bygger på samme lette stel med aeroformning som resten af BeLiv SL-serien og har præcis styring. Farven er Unicorn White.</p>' ],
	[ 'eans' => [ '8717842037027' ], 'html' => '<p>Fluid Rower Neon Pro XL er en vandroeromaskine med ti justerbare vandmodstandsniveauer. Den har ergonomisk håndtag, komfortabelt sæde og en Bluetooth-monitor med Power Graph, så du kan følge din teknik. Konstruktionen er i stål med industrielt udtryk.</p>' ],
	[ 'eans' => [ '5704796045485' ], 'html' => '<p>ASG SkiErgometer er en skimaskine til helkropstræning inspireret af langrend. Du får 16 modstandsniveauer og 21 indbyggede træningsprogrammer, og Bluetooth giver forbindelse til Kinomap og Zwift.</p>' ],
	[ 'eans' => [ '8029975809984' ], 'html' => '<p>Toorx BRX AIRMAG 7000 er en motionscykel, hvor modstanden kan være ren luft eller luft kombineret med magnet. Intensiteten er trinløs. Cyklen har et display med mange funktioner og app-kompatibilitet.</p>' ],
	[ 'eans' => [ '8029975809724' ], 'html' => '<p>Toorx Traveller er et løbebånd med 2,5/3,5 HP motor og topfart på 18 km/t. Det er app-ready 3.0 med kompatibilitet til Zwift og Kinomap, og otte puder dæmper stødene.</p>' ],
	[ 'eans' => [ '5707965262584' ], 'html' => '<p>Avenue Empire Carbon er Avenues første model med et stel i helcarbon. Stellet er udviklet over flere år og forener lav vægt, stivhed og aerodynamik i en citybike. Udgaven her er herremodel med Shimano 105 i farven Shiny Dark Blue.</p>' ],
	[ 'eans' => [ '4054571509901' ], 'html' => '<p>Cube Nulane C:62 SLT har fuld carbonramme og carbongaffel, elektronisk 1x13 gear og hydrauliske skivebremser. Cyklen er lavet til by og grusveje. Farven er Greensmoothie n Green.</p>' ],
	[ 'eans' => [ '5714605005807' ], 'html' => '<p>Relax Dual Cable Cross med spejl er en cable cross til fitnesscentre og motionsrum. Der er to vægtmagasiner på hver 36 kg, indbygget spejl og støttepind, og konstruktionen er pladsbesparende.</p>' ],
	[ 'eans' => [ '5714241012597' ], 'html' => '<p>Olympisk decline bænkpres fra UpForm er designet til at træne brystmuskulaturen i en nedadgående vinkel.</p>' ],
	[ 'eans' => [ '5714241012603' ], 'html' => '<p>Olympisk incline bænkpres fra UpForm er en professionel bænk med skrå vinkel til bænkpres.</p>' ],
	[ 'eans' => [ '5714237009785' ], 'html' => '<p>Odin PRO CPU Bumper Plates er et sæt olympiske bumper-vægtskiver på 150 kg til konkurrence og kommercielle fitnesscentre. Skiverne kan tåle at blive tabt.</p>' ],
	[ 'eans' => [ '5714605004749' ], 'html' => '<p>Powertec Power Rack med 125 kg 50 mm vægtsæt i sort er en pakke med power rack, Powertec WB Utility Bench og vægtpakke.</p>' ],
	[ 'eans' => [ '5714605004664' ], 'html' => '<p>Pakken fra Powertec indeholder Half Rack i sort, Powertec WB Utility Bench og en Peak Fitness bumper plates-vægtskivepakke på 125 kg.</p>' ],
	[ 'eans' => [ '4895147803623' ], 'html' => '<p>MX Select er et justerbart vægtstangsæt fra 12,8 til 45,5 kg med klassisk vægtstang og EZ-curl-stang og fælles opbevaringsstativ. Et patenteret låsesystem holder skiverne fast, og du skifter vægt med et drej i ti trin på cirka 3,6 kg.</p>' ],
	[ 'eans' => [ '8029975812267' ], 'html' => '<p>Everfit TFK 590 er et løbebånd med hastighed op til 18 km/t og 15 elektroniske stigningsniveauer. Det kan bruges med Zwift og Kinomap via Smart Bluetooth, og løbefladen er stor med effektiv støddæmpning.</p>' ],
	[ 'eans' => [ '8029975999647' ], 'html' => '<p>Everfit TFK 855 Slim er et foldbart løbebånd med hastighed op til 20 km/t i trin på 0,1 km/t. Stigningen er elektronisk på 12 % i 12 niveauer, og App Ready 3.0 giver Bluetooth-forbindelse.</p>' ],
	[ 'eans' => [ '8717231367032', '8717231367025', '8717231367049' ], 'html' => '<p>Gazelle Chamonix S11 er en turcykel med sporty udtryk og komfort. Den har Alfine-nav med 11 gear, hydrauliske skivebremser og vedligeholdelsesfrit remtræk. Udgaven her er en herremodel fra 2026 i grå.</p>' ],
	[ 'eans' => [ '8717231367018', '8717231366998', '8717231367001' ], 'html' => '<p>Gazelle Chamonix S11 dame fra 2026 i grå er en turcykel med Alfine-nav med 11 gear, hydrauliske skivebremser og remtræk, der ikke kræver meget vedligehold.</p>' ],
	[ 'eans' => [ '5714237010415' ], 'html' => '<p>Odin Hex-sættet på 340 kg består af otte sæt hex-håndvægte fra 12,5 til 30 kg og et rack. Sættet kan bruges på alle niveauer og passer i motionsrum.</p>' ],
	[ 'eans' => [ '4054571541338', '4054571541345', '4054571541352', '4054571541376', '4054571541383', '4054571541390', '4054571541406' ], 'html' => '<p>Cube Nulane C:62 SLX FE kombinerer carbonstellet med fuldt pendlerudstyr: skærme, semi-integreret bagagebærer og ACID Pro-D 100 forlygte. Drivværket er Shimano Cues 1x11, og dækkene er 45 mm Schwalbe G-One Overland. Modellen er årgang 2027.</p>' ],
	[ 'eans' => [ '5714237009273' ], 'html' => '<p>Odin PRO Super Over Pull er et komplet rack til kommercielle fitnesscentre og motionsrum. Du træner inde i racket, i modsætning til et klassisk squat-stativ eller bænkpres-rack.</p>' ],
	[ 'eans' => [ '5751940130856' ], 'html' => '<p>Abilica HR 500 Half Rack Olympic er en komplet styrkepakke med half rack og opbevaring af vægtskiver, justerbar bænk, lat pulldown-modul, olympiske vægtskiver på 150 kg og stang.</p>' ],
	[ 'eans' => [ '5714237015830' ], 'html' => '<p>Odin Valhalla er en multistation med Smith-rack, kabeltræning og plate load til vægtskiver. Vægtmagasinet er på 144 kg, og alle tre træningsformer ligger i samme maskine.</p>' ],
	[ 'eans' => [ '5714237018640' ], 'html' => '<p>Odin C1000 er en crosstrainer til hjemmet med 10,1 tommer TFT-touchskærm, lang skridtlængde og 36 forudindstillede træningsprogrammer.</p>' ],
	[ 'eans' => [ '8717842036341' ], 'html' => '<p>Tunturi Platinum S20 er en spinningcykel med automatisk PMS-bremsesystem og 32 modstandsniveauer. Pedalerne er dobbelte, med både SPD og stropper, og farve-LCD-monitoren er app-kompatibel og har tabletholder.</p>' ],
	[ 'eans' => [ '8717842032442' ], 'html' => '<p>Tunturi Signature T40 er et foldbart løbebånd med 47 programmer og hastighed op til 16 km/t. Det er kompatibelt med Zwift, Kinomap og Tunturi Routes, og løbefladen har diamant-mønster mod glidning.</p>' ],
	[ 'eans' => [ '4044163022819' ], 'html' => '<p>Top Sport SP 5000 er en multistation til helkropstræning hjemme. Vægtpakken er på 60 kg og kan udvides.</p>' ],
	[ 'eans' => [ '5704796045768' ], 'html' => '<p>ASG PowerRun har brushless DC-motor på 2,5 HK med 3,75 HK peak og hastighed op til 22 km/t. Stigningen er automatisk i 15 niveauer, og der er 20 træningsprogrammer. Maksimal brugervægt er 150 kg.</p>' ],
	[ 'eans' => [ '8029975809670' ], 'html' => '<p>Toorx BRX 5000 er en airbike med automatisk og justerbar luftmodstand. Den viser træningsdata, kan kobles til apps og kan indstilles i to akser. Brugervægten er høj.</p>' ],
	[ 'eans' => [ '8029975996318' ], 'html' => '<p>Toorx MSX50 er en multistation til helkropstræning hjemme med øvelser til overkrop, ben og core.</p>' ],
	[ 'eans' => [ '8029975810409' ], 'html' => '<p>Everfit TFK 490 er et foldbart løbebånd med 15 elektroniske stigningsniveauer og Soft Tech støddæmpning. Det er kompatibelt med Zwift og Kinomap.</p>' ],
	[ 'eans' => [ '7051943736115' ], 'html' => '<p>Abilica Premium FC BT er en crosstrainer til hjemmet og virksomheder med 51 cm skridtlængde, 32 modstandsniveauer og justerbare skinner.</p>' ],
	[ 'eans' => [ '7051944157193' ], 'html' => '<p>Abilica Premium Rower 95 er en romaskine med både luft- og magnetmodstand, Power Zones og app-tilslutning. Den kan bruges til CrossFit, HYROX og hjemmetræning.</p>' ],
	[ 'eans' => [ '7051944175302' ], 'html' => '<p>Abilica TM 45 BT er et løbebånd med app-tilkobling og god dæmpning. Det kan bruges til intervaller, farttræning og konditionstræning.</p>' ],
	[ 'eans' => [ '5714241012610' ], 'html' => '<p>Olympisk flad bænkpres fra UpForm er designet til effektiv træning af brystmuskler.</p>' ],
	[ 'eans' => [ '7616185496496', '7616185496502' ], 'html' => '<p>Scott Metrix 10 er en fitnesscykel med lige styr, til dig der vil have landevejsfart med opret og komfortabel siddeposition. Den har 11 gear fra Shimano Cues og brede 40 mm dæk. Modellen er årgang 2027 i farven Iron Grey.</p>' ],
	[ 'eans' => [ '5714605004657' ], 'html' => '<p>Powertec-pakke med Half Rack i sort, Powertec WB Utility Bench og et sort 50 mm vægtsæt på 125 kg med 220 cm vægtstang.</p>' ],
	[ 'eans' => [ '5714605004701' ], 'html' => '<p>Pakke med Powertec Half Rack i gul, Powertec WB Utility Bench og et sort 50 mm vægtsæt på 125 kg fra Peak Fitness.</p>' ],
	[ 'eans' => [ '5714605004671' ], 'html' => '<p>Pakken indeholder Powertec Half Rack i gul, Powertec WB Utility Bench og et bumper-vægtsæt på 125 kg.</p>' ],
	[ 'eans' => [ '7616185493426', '7616185493433', '7616185493457' ], 'html' => '<p>Scott Vitess 10 Wave er topmodellen i serien med lavt gennemstigningsstel, så det er nemt at stige af og på. Den har luftaffjedret RST-forgaffel, 22 gear fra Shimano Cues og lygter drevet af navdynamo. Modellen er årgang 2027 i Willow Green.</p>' ],
	[ 'eans' => [ '5714241015352' ], 'html' => '<p>Leg Master er en maskine til ben- og lægtræning til fitnesscentre. Den leveres som skaffevare med ca.</p>' ],
	[ 'eans' => [ '4054571541239', '4054571541253' ], 'html' => '<p>Cube Nulane C:62 SLX er seriens carbonmodel og vejer 9,6 kg. Stellet er C:62 Advanced Twin Mold, drivværket Shimano Cues 1x11 med 11-50T, og dækkene er tubeless-klare Schwalbe G-One R Pro i 45 mm. Modellen er årgang 2027.</p>' ],
	[ 'eans' => [ '7616185493600', '7616185493617' ], 'html' => '<p>Scott Vitess 10 er topmodellen i Vitess-serien med luftaffjedret RST-forgaffel og 22 gear fra Shimano Cues. Navdynamo driver lygterne, og stellet er let aluminium. Modellen er årgang 2027 i Cinder Grey.</p>' ],
	[ 'eans' => [ '8717842027769' ], 'html' => '<p>Tunturi HG60 er en multistation til helkropstræning hjemme med justerbart ryglæn og 70 kg vægtstak. Stationen kan bruges af både begyndere og erfarne.</p>' ],
	[ 'eans' => [ '8717842036662' ], 'html' => '<p>Tunturi Platinum S10 er en spinningcykel med PMS-bremsesystem og 32 modstandsniveauer. Pedalerne er dobbelte, med SPD og stropper, og LCD-monitoren er app-kompatibel med tabletholder.</p>' ],
	[ 'eans' => [ '4044163025452' ], 'html' => '<p>Top Sport TM 4500 er et foldbart løbebånd med hastighed op til 20 km/t og 15 hældningsniveauer. Det har stor LED-skærm med app-integration, Bluetooth-højttalere, støddæmpning og automatisk smøring.</p>' ],
	[ 'eans' => [ '0885652025133' ], 'html' => '<p>Adidas T-23 er et løbebånd med 4,5 HK motor, 24 forudindstillede programmer og elektronisk hældning i 15 niveauer. Motoren er støjsvag.</p>' ],
	[ 'eans' => [ '8029975996134' ], 'html' => '<p>Toorx BRX 3000 er en ergometercykel med 16 kg svinghjul og 32 digitale modstandstrin. Bluetooth, app-integration og trådløs pulsmåling er med, og programmerne dækker blandt andet watt og HRC.</p>' ],
	[ 'eans' => [ '7051941311208' ], 'html' => '<p>Abilica MultiPower Multigym by BodyCraft har 90 kg vægtmagasin, patenteret pec-dec-system og op til 180 kg belastning. Den kan bruges derhjemme eller i virksomheden.</p>' ],
	[ 'eans' => [ '7051944121774' ], 'html' => '<p>Spirit AB900+ er en airbike med luftdrevet isokinetisk modstandssystem, bygget på en klassisk træningsmetode.</p>' ],
	[ 'eans' => [ '5714241014782' ], 'html' => '<p>Kompakt benpres- og lægmaskine til home gym eller fitnesscentre med begrænset plads. Den leveres som skaffevare fra fjernlager med ca.</p>' ],
	[ 'eans' => [ '5714241012948' ], 'html' => '<p>Squat rack og bænkpres-rack til fitnesscentre med fokus på sikkerhed.</p>' ],
	[ 'eans' => [ '5712701027907', '5712701027914', '5712701027921', '5712701027938' ], 'html' => '<p>Motobécane 1976-26 Randonneur er en fuldt udstyret touring- og pendlercykel med klassisk retrostil og moderne køreegenskaber. Gearingen er 2x11. Udgaven her er årgang 2026 i blank sort.</p>' ],
	[ 'eans' => [ '5712701027945', '5712701027952', '5712701027969', '5712701027976' ], 'html' => '<p>Motobécane 1976-26 Randonneur er en touring- og pendlercykel i retrostil med 2x11 gear. Farven er mat mørkeblå, og modellen er årgang 2026.</p>' ],
	[ 'eans' => [ '5712705004584', '5712705004607', '5712705004591' ], 'html' => '<p>Avenue Airbase Metal er en damecykel i metallisk sølv med udvendige, hurtigtskiftende 10-gear. Modellen er fra 2025.</p>' ],
	[ 'eans' => [ '5712705004522', '5712705004546', '5712705004539' ], 'html' => '<p>Avenue Broadway Metal er en damecykel i metallisk sølv med indvendige 7-gear, der kræver minimal vedligeholdelse. Modellen er fra 2025.</p>' ],
	[ 'eans' => [ '5712705004515', '5712705004492', '5712705004508' ], 'html' => '<p>Avenue Broadway Metal i herreudgave har indvendige 7-gear med minimalt vedligehold. Farven er metallisk sølv, og modellen er fra 2025.</p>' ],
	[ 'eans' => [ '5712705004577', '5712705004560', '5712705004553' ], 'html' => '<p>Avenue Airbase Metal i herreudgave er en cykel i metallisk sølv med udvendige 10-gear. Modellen er fra 2025.</p>' ],
	[ 'eans' => [ '5714237009266' ], 'html' => '<p>Odin PRO Olympic Flat/Incline/Decline Bench samler tre bænkpres-stationer i ét rack. Du vælger selv, om du vil træne flad, skrå eller nedadgående bænkpres.</p>' ],
	[ 'eans' => [ '5714605005821' ], 'html' => '<p>Peak Fitness C5 er en forbedret crosstrainer med synlige justeringstal, beregnet til hele familien.</p>' ],
