	[ 'eans' => [ '5714605004688' ], 'html' => '<p>Powertec-pakken indeholder Half Rack i sort, Powertec WB Utility Bench og Peak Fitness 95 kg 50 mm PU-vægtsæt.</p>' ],
	[ 'eans' => [ '5714605004770' ], 'html' => '<p>Powertec WB Levergym er en multitræningsmaskine, der kun er 208 cm høj og har lat pull down-funktion. Denne pakke leveres med 77 kg 50 mm vægtskiver.</p>' ],
	[ 'eans' => [ '5751940130894' ], 'html' => '<p>Abilica HR 500 Half Rack med bumper-vægtskiver på 150 kg og bænk er en pakke til varieret og tung træning derhjemme.</p>' ],
	[ 'eans' => [ '7051941304118' ], 'html' => '<p>Abilica Hex-håndvægtsæt indeholder 11 par hex-håndvægte fra 6 til 30 kg og stativ.</p>' ],
	[ 'eans' => [ '0848688029001' ], 'html' => '<p>Concept2 BikeErg PM5 er en motionscykel med luftmodstand: jo hårdere du træder, jo større bliver belastningen. Computeren er en PM5.</p>' ],
	[ 'eans' => [ '5704519001163', '5704519001170', '5704519001187', '5704519001491', '5704519002139' ], 'html' => '<p>NubisPro XL 2.0 er en oppustelig mobil massagebrik til fysioterapeuter, massører og alternative behandlere, der har brug for en let briks, som kan flyttes.</p>' ],
	[ 'eans' => [ '5704519000982', '5704519000999', '5704519001002', '5704519001019', '5704519001026', '5704519001033' ], 'html' => '<p>NubisPro 2.0 er en mobil massagebrik til fysioterapeuter, massører og alternative behandlere, som dagligt har brug for en let briks, der er nem at tage med.</p>' ],
	[ 'eans' => [ '5714237011092' ], 'html' => '<p>Odin Pro Hip Thrust Træningsbænk er lavet til træning af baller og ben i fitnesscentre. Bænken er bygget til at give medlemmerne en dedikeret station til hip thrust.</p>' ],
	[ 'eans' => [ '4054571509802' ], 'html' => '<p>Cube Nulane C:62 SLX er city-gravel i letvægts C:62 carbon. Cyklen er til dig, der vil køre hurtigt, komfortabelt og stilrent på både asfalt og grus. Farven er Electricblue n Blue.</p>' ],
	[ 'eans' => [ '7616185493204', '7616185493235', '7616185493211', '7616185493228' ], 'html' => '<p>Scott Vitess 15 er en klassisk damecykel til hverdagskørsel og pendling. Remtrækket er vedligeholdelsesfrit og kombineret med Shimano Nexus 8-gears indvendigt gear, så der hverken er olie eller synlig kæde. Modellen er årgang 2027 i Flaky Black.</p>' ],
	[ 'eans' => [ '7616185492894', '7616185492900', '7616185492917', '7616185492924' ], 'html' => '<p>Scott Vitess 15 Slope er en damecykel med skrånende stel og vedligeholdelsesfrit remtræk. Shimano Nexus 8-gears indvendigt gear holder cyklen ren, og navdynamoen driver lygterne. Modellen er årgang 2027 i Silk Blue.</p>' ],
