	[ 'eans' => [ '5751940130870' ], 'html' => '<p>Abilica HR 500 Half Rack Olympic med bænk og 150 kg vægt indeholder half rack, olympiske vægtskiver, stang, bænk og låse samt opbevaring til vægtskiverne.</p>' ],
