	[ 'eans' => [ '8029975810683' ], 'html' => '<p>Everfit TFK 390 er et foldbart løbebånd med hastighed op til 16 km/t. Det er kompatibelt med Zwift og Kinomap, og Soft Tech støddæmpning gør løbeturen skånsom.</p>' ],
