	[ 'eans' => [ '5712705006359', '5712705006366', '5712705006373' ], 'html' => '<p>Avenue Airbase i Shiny Copper er en herrecykel fra 2026 med organiske, aerodynamiske linjer og Shimano Tiagra 10 gear. Bremserne er hydrauliske.</p>' ],
