	[ 'eans' => [ '5751940130863' ], 'html' => '<p>Abilica HR 500 Half Rack Olympic med bænk og 110 kg vægt indeholder half rack, olympiske vægtskiver, stang, bænk og låse samt opbevaring til vægtskiverne.</p>' ],
	[ 'eans' => [ '5714237009006' ], 'html' => '<p>Odin Hex Håndvægtsæt på 110 kg består af hex-håndvægte fra 1 til 10 kg og er velegnet til erhvervsbrug. Vægten står tydeligt på hver håndvægt.</p>' ],
	[ 'eans' => [ '5714237015304' ], 'html' => '<p>Odin Elite Power Rack er et power rack til kommercielle træningscentre og firmagymmer. Konstruktionen har kraftige 70x70 mm profiler og solide J-hooks.</p>' ],
	[ 'eans' => [ '8717842028230' ], 'html' => '<p>Tunturi WT80 er en foldbar multi-træningsmaskine til hjemmet. Den kan bruges med både 30 mm og 50 mm vægtskiver, og sæde og ryglæn er justerbare.</p>' ],
	[ 'eans' => [ '8717842036549' ], 'html' => '<p>Tunturi Signature E80 er en motionscykel med vedligeholdelsesfri induktionsbremse og 48 modstandsniveauer. Du får Comfort+ sæde og pedaler samt et Bluetooth AI-display med farvekoder, apps og tabletholder.</p>' ],
	[ 'eans' => [ '8717842036563' ], 'html' => '<p>Tunturi Signature C60-R er en crosstrainer med ledskånende bevægelse og 48 modstandsniveauer. Bluetooth AI-skærmen er app-kompatibel.</p>' ],
	[ 'eans' => [ '0885652036733' ], 'html' => '<p>Adidas Crossover Kabeltræk har 160 kg vægtmagasin og kombinerer kabelstation, power rack og pull-up station. Der er 40 justerbare kabelpositioner.</p>' ],
	[ 'eans' => [ '5704796045744' ], 'html' => '<p>ASG Core Pro er et løbebånd med DC-motor på 2,0 HK (3,0 HK peak) og hastighed op til 18 km/t. Stigningen er automatisk i 15 niveauer, og der er 16 programmer. Båndet kan bruges med FITT Home, Kinomap og Zwift.</p>' ],
	[ 'eans' => [ '5704796045751' ], 'html' => '<p>ASG RunX er et løbebånd med DC-motor på 2,5 HK (3,75 HK peak) og hastighed op til 20 km/t. Stigningen er automatisk i 15 niveauer, løbefladen er 130 x 48 cm, og maksimal brugervægt er 150 kg.</p>' ],
	[ 'eans' => [ '5704796046024' ], 'html' => '<p>StormRunner Premium er et foldbart løbebånd med 2,0 HK motor og hastighed op til 18 km/t. Det er Bluetooth-kompatibelt med FITT Home, Kinomap og Zwift, og løbefladen er 120 x 42 cm.</p>' ],
	[ 'eans' => [ '8029975994444' ], 'html' => '<p>Toorx CSX 70 er en cable cross med dobbelt vægtmagasin på 2 x 50 kg. Håndtagene er justerbare, og der følger tilbehør med. Konstruktionen har en pull-up bar.</p>' ],
	[ 'eans' => [ '8029975996684' ], 'html' => '<p>Toorx RWX 3000 er en foldbar vandroeromaskine med seks justerbare vandmodstandsniveauer. LCD-skærmen har fem træningsprogrammer, og der er indbygget pulsmåler.</p>' ],
	[ 'eans' => [ '7051943746619' ], 'html' => '<p>Abilica Mill 30 er et sammenklappeligt løbebånd med 2,0 HK DC-motor, hastighed op til 19 km/t og 12 stigningsniveauer. Det kan kobles til Zwift og Kinomap.</p>' ],
	[ 'eans' => [ '0578962388511' ], 'html' => '<p>ATX Soft Plyobox-sættet består af fire polstrede plyobokse i højderne 15, 30, 45 og 60 cm. Boksene kan bruges hver for sig eller forbindes med velcro til træning af springkraft og eksplosivitet.</p>' ],
