	[ 'eans' => [ '5714241011132' ], 'html' => '<p>Håndvægtsholder med to hylder til hexagon-håndvægte. Der er plads til op til 10 par, afhængigt af størrelsen. Håndvægte medfølger ikke.</p>' ],
	[ 'eans' => [ '5714237006319' ], 'html' => '<p>Bænkpres-bænk fra Odin til homegym. Racket er enkelt og brugervenligt, og bænkpres er en af de mest populære øvelser.</p>' ],
	[ 'eans' => [ '5714237017254' ], 'html' => '<p>Valkyrie PR200 er en foldbar pilates-reformer til dig, der vil have en klassisk og professionel oplevelse derhjemme.</p>' ],
	[ 'eans' => [ '7051944155274' ], 'html' => '<p>FID 550 er en justerbar træningsbænk til tung styrketræning med maksimal belastningskapacitet på 500 kg.</p>' ],
