	[ 'eans' => [ '7051943733459' ], 'html' => '<p>KettleBell Covered på 8 kg bruges eksplosivt og dynamisk, i en træningsform som er flere hundrede år gammel.</p>' ],
	[ 'eans' => [ '5704519002702' ], 'html' => '<p>Yogamåtte i sort TPE, blød, let og skridsikker og fri for skadelige stoffer.</p>' ],
	[ 'eans' => [ '5714241001546' ], 'html' => '<p>Vægtmanchetter til ankler og håndled. Du får 2 manchetter à 5 kg, i alt 10 kg.</p>' ],
	[ 'eans' => [ '5714241016526' ], 'html' => '<p>Mini squat blocks til knæbøjninger med vægtstang. De hjælper med teknik og mobilitet i anklerne og aflaster ryggen.</p>' ],
	[ 'eans' => [ '5714241001799' ], 'html' => '<p>Justerbar stepbænk i medium med tre niveauer: 10, 15 og 20 cm.</p>' ],
	[ 'eans' => [ '5714241000365' ], 'html' => '<p>Rund gummi-håndvægt på 7,5 kg i klassisk roundstyle, som kendes fra centre og konkurrencer.</p>' ],
	[ 'eans' => [ '5714241005179' ], 'html' => '<p>Slyngetræner Black-PRO til funktionel træning med kropsvægt for styrke, stabilitet og mobilitet.</p>' ],
	[ 'eans' => [ '5784933516054' ], 'html' => '<p>Massageapparat med 4 hoveder til muskelmassage af ryg, skuldre, nakke og bryst.</p>' ],
	[ 'eans' => [ '5714237005855', '5714237005848' ], 'html' => '<p>Slyngetræner fra Odin til hjemmet. Den kan hænges i loftet eller sættes fast i en dør. Fås i sort og sort/rød.</p>' ],
	[ 'eans' => [ '5701000090828' ], 'html' => '<p>Bumper plate på 5 kg i gummi og 50 mm hul fra Titan Life, til olympiske stænger.</p>' ],
	[ 'eans' => [ '3700006350501' ], 'html' => '<p>Håndholdt foam roller Grid STK fra Trigger Point til selvmassage af muskler.</p>' ],
	[ 'eans' => [ '0885652020633' ], 'html' => '<p>Ankelvægte på 1,5 kg pr. stk. fra Reebok, 2 stk. Bruges til at øge intensiteten i træningen.</p>' ],
	[ 'eans' => [ '5714237013683' ], 'html' => '<p>Gummibelagt vægtskive på 10 kg i sort til Bodypump, styrketræning og funktionel træning.</p>' ],
	[ 'eans' => [ '5714237014598' ], 'html' => '<p>Rund håndvægt på 5 kg med gummibelagte hoveder og fast forkromet håndtag. Sælges som 1 stk.</p>' ],
	[ 'eans' => [ '5714237016288' ], 'html' => '<p>Klassisk jern-vægtskive på 10 kg til olympiske stænger med 50 mm hul. Sælges enkeltvis.</p>' ],
	[ 'eans' => [ '9781492567707' ], 'html' => '<p>Pilates Anatomy, second edition, er en engelsksproget bog med illustrerede øvelser. Du kan vælge blandt 46 øvelser, der træner bestemte dele af kroppen.</p>' ],
	[ 'eans' => [ '5714241004400' ], 'html' => '<p>Medicinbold på 2 kg fra Nordic Strength med ru, bulet overflade, der giver et godt greb.</p>' ],
	[ 'eans' => [ '5701000101678', '5714237004247' ], 'html' => '<p>Krom-håndvægt på 6 kg med nubret håndtag og godt greb. Vægten står markeret på siderne, og prisen gælder pr. stk.</p>' ],
	[ 'eans' => [ '5714237002489' ], 'html' => '<p>Slam Ball på 12 kg fra Odin, til øvelser for ben, ryg, skuldre, biceps og triceps.</p>' ],
	[ 'eans' => [ '7051943747562' ], 'html' => '<p>Kettlebell på 10 kg i støbejern med mat overflade og godt greb.</p>' ],
	[ 'eans' => [ '5703543152667' ], 'html' => '<p>Ball-Punktur massagebold fra Select med 21 cm i diameter. Den er udviklet af en dansk træningsvejleder og kombinerer massage, akupunktur og zoneterapi.</p>' ],
	[ 'eans' => [ '5714237007743' ], 'html' => '<p>HeavyRope sjippetov på 1.500 g i X-Heavy-udgaven, til hård træning. Findes i flere sværhedsgrader.</p>' ],
	[ 'eans' => [ '0885652028288', '0885652028295', '0885652028301' ], 'html' => '<p>Yogamåtte på 6 mm fra Reebok til yoga, pilates, core og mobilitet. Fås i Ashen Lilac, Black og Dark Green.</p>' ],
	[ 'eans' => [ '5055436111047' ], 'html' => '<p>Sæt med to Reebok-træningselastikker i level 1 og level 2 til hjemmetræning.</p>' ],
	[ 'eans' => [ '5055436111818' ], 'html' => '<p>DELTA Slam Ball på 2 kg fra Reebok, designet til at holde til hård træning.</p>' ],
	[ 'eans' => [ '5714237002274' ], 'html' => '<p>Elite Cable Speed Rope på 300 cm. Det er et sjippetov til dubble unders.</p>' ],
	[ 'eans' => [ '5714237002717' ], 'html' => '<p>Seated row-greb med smalt gummigreb til trækstationer og kabeltårne. Bredde pr. håndtag er 17,5 cm, og center til center er 14 cm.</p>' ],
	[ 'eans' => [ '5714237003318' ], 'html' => '<p>CrossFit PowerBand i niveau 8, 10,1 cm bred og XXX-Hard, til pull-ups og stræk.</p>' ],
	[ 'eans' => [ '5714237002830' ], 'html' => '<p>Dobbelt trækhåndtag med kort skovlgreb, som spændes på homegym og multimaskiner med karabinhage.</p>' ],
	[ 'eans' => [ '5714237003257' ], 'html' => '<p>CrossFit PowerBand i niveau 3, 26 mm bred og Light, til pull-ups og stræk.</p>' ],
	[ 'eans' => [ '5714237008979' ], 'html' => '<p>Pakke med en sort træningsmåtte på 183 × 61 × 1,5 cm og seks elastikker fra Odin.</p>' ],
	[ 'eans' => [ '5714237008924' ], 'html' => '<p>Ophængskæde til sandsæk med 4 arme. Kæden er 55 cm lang, og hver arm er 37 cm. Til op til 4 monteringsbeslag.</p>' ],
	[ 'eans' => [ '6951376138245' ], 'html' => '<p>Klassiske håndvægte i neopren på 3 kg, til aerobic og steptræning. Sælges parvis.</p>' ],
	[ 'eans' => [ '5714237005350' ], 'html' => '<p>Træningsmåtte i blå, 183 × 61 × 1,5 cm, til mave- og yogaøvelser.</p>' ],
	[ 'eans' => [ '0885652020428', '0885652020411' ], 'html' => '<p>Træningsmåtte fra Reebok, 183 × 61 × 1 cm. Fås i blå og sort.</p>' ],
	[ 'eans' => [ '0885652023511' ], 'html' => '<p>Foam roller fra Reebok, som kan bruges til at løsne spændt væv og fremme restitutionen.</p>' ],
	[ 'eans' => [ '0885652024532', '0885652025584', '0885652025577' ], 'html' => '<p>Yogamåtte på 4 mm fra Reebok i motiverne Fluid Motion, Chakra og Pose.</p>' ],
	[ 'eans' => [ '5714237014260', '5714237014338' ], 'html' => '<p>Foam roller med nubret overflade, medium hård og 60 cm lang, til massage, restitution og mobilitetstræning. Fås i sort og blå.</p>' ],
	[ 'eans' => [ '5714237014284' ], 'html' => '<p>Foam roller med glat overflade, medium hård og 60 cm lang, i sort. Til massage, restitution og mobilitet.</p>' ],
	[ 'eans' => [ '5714237015069' ], 'html' => '<p>Atlet vægtvest på 4 kg. En kompakt løbevægtvest til løb, gang og trappetræning.</p>' ],
	[ 'eans' => [ '8717842025512' ], 'html' => '<p>Justerbar vinyl-håndvægt op til 15 kg med sikker låsemekanisme til muskeltræning.</p>' ],
	[ 'eans' => [ '8717842038666' ], 'html' => '<p>Platinum fractional vægtskiver i hvid, 2 × 0,5 kg, til små justeringer af belastningen. Gummiet dæmper støj og skåner gulvet.</p>' ],
	[ 'eans' => [ '0885652034975', '0885652035002', '0885652034968' ], 'html' => '<p>Træningshandsker i sort med CLIMAWARM, der isolerer og transporterer sved, reflekterende detaljer og præget greb. Til løb, vandring og cykling i kulde. Fås i XS, S og XL.</p>' ],
	[ 'eans' => [ '8029975990330' ], 'html' => '<p>Butterfly Kit til Everfit WBK-500, til butterfly-øvelser for brystmusklerne. Samles uden avanceret værktøj.</p>' ],
	[ 'eans' => [ '8029975950228' ], 'html' => '<p>Gummibelagt vægtskive på 10 kg til stænger med 25 mm skiveholdere. Støjdæmpende og beskytter skive og underlag.</p>' ],
	[ 'eans' => [ '8029975950440' ], 'html' => '<p>Vægtskiven fra Toorx vejer 5 kg og er beklædt med gummi, som tager toppen af støjen, når skiverne lægges på stangen eller sættes fra. Den passer til olympiske vægtstænger med 50 mm skiveholdere og lader dig skrue op for belastningen i små trin.</p><p>Farven er sort.</p>' ],
	[ 'eans' => [ '0009283587666' ], 'html' => '<p>Everlast Evergel er et par håndbind i pink og sort til boksetræning i størrelse M/L. Evergel-puderne lægger sig over knoerne og tager det værste stød ud af slagene, og en justerbar velcrorem holder håndleddet stabilt.</p><p>Konstruktionen er let og åndbar, og bindene tages hurtigt på.</p>' ],
	[ 'eans' => [ '5050787200938' ], 'html' => '<p>Sorte håndbind fra Everlast med Evergel-puder over knoerne, så slag mod sandsæk eller pads føles mere dæmpede. Velcroremmen kan strammes efter behov og giver støtte om håndleddet.</p><p>Materialet er let og åndbart, og de er hurtige at få på inden træning.</p>' ],
	[ 'eans' => [ '0009283516529' ], 'html' => '<p>Everlast Evergel håndbind i sort, størrelse L. Puder af Evergel sidder ved knoerne og dæmper stød, mens den justerbare velcrorem giver håndleddet ekstra støtte under boksetræningen.</p><p>Bindene er lette, åndbare og hurtige at tage på.</p>' ],
	[ 'eans' => [ '0009283516512' ], 'html' => '<p>Her er Everlasts Evergel håndbind i sort og størrelse M. Evergel-puderne beskytter knoerne mod stød, og velcroremmen kan justeres, så håndleddet får den støtte, du ønsker.</p><p>Konstruktionen er let og åndbar, og bindene sidder hurtigt.</p>' ],
	[ 'eans' => [ '0009283516536' ], 'html' => '<p>Sort håndbind i størrelse XL fra Everlast. Evergel-puder over knoerne tager brodden af stød, og en justerbar velcrorem holder om håndleddet og støtter det.</p><p>Bindene er lette og åndbare og kan tages på i en håndevending.</p>' ],
	[ 'eans' => [ '7051943732841' ], 'html' => '<p>SoftBalance fra Abilica er en blød balancepude af plast fyldt med luft. Den bruges til balanceøvelser og koordinationstræning, og du kan stå, sidde eller ligge på den, så underlaget bliver ustabilt og kroppen skal arbejde for at holde position.</p>' ],
	[ 'eans' => [ '7051944208475' ], 'html' => '<p>Fodpumpen til Abilicas AirTrack rummer 6 liter og har 2-vejs funktion, så den både blæser luft ind og suger den ud igen. Det gør det hurtigt at pumpe en AirTrack op og lade luften slippe ud, når du pakker sammen. Pumpen kan også bruges til andet oppusteligt udstyr.</p>' ],
	[ 'eans' => [ '7051944217569' ], 'html' => '<p>SquatPad fra Abilica er en vægtstangspude, der lægges om stangen for at skåne nakke og hofter under squats og hip thrust. Puden er lavet af NBR-skum med et slidstærkt betræk og lukkes med velcro, så den bliver siddende på stangen.</p>' ],
	[ 'eans' => [ '0847585006306' ], 'html' => '<p>TRX Door Anchor er til dig, der ikke har et loft eller en væg at hænge slyngetræneren i. Ankeret sættes på en dør og gør det muligt at træne med din TRX derhjemme, uden at døren tager skade.</p>' ],
	[ 'eans' => [ '3700006350525' ], 'html' => '<p>Trigger Point Nano Foot Roller er en lille rulle til fødder og underarme. Den er lavet til at øge fleksibiliteten og løsne mindre muskelspændinger og ømhed i de områder. Rullen måler 16,5 x 7 cm og er let at have med i tasken.</p>' ],
	[ 'eans' => [ '5714241001621' ], 'html' => '<p>Balancepuden i blåt TPE-skum giver et ustabilt underlag, så kroppen hele tiden må justere sig. Det aktiverer de små stabiliserende muskler, som ofte overses i almindelig træning, og styrker koordinationen.</p><p>Skummet er slidstærkt, og puden kan bruges til både stående øvelser og genoptræning.</p>' ],
	[ 'eans' => [ '5714241001638' ], 'html' => '<p>Denne lilla balancepude er støbt i slidstærkt TPE-skum. Den ustabile overflade tvinger fødderne og kernemusklerne til at arbejde, og du træner dermed balance og koordination.</p><p>Brug den som underlag ved stående øvelser eller som en blød platform til andre bevægelser.</p>' ],
	[ 'eans' => [ '5714241001645' ], 'html' => '<p>Sort balancepude i TPE-skum, som udfordrer balancen og aktiverer de små stabiliserende muskler. Når underlaget giver efter, må kroppen justere sig konstant, og det træner koordinationen.</p><p>Skummet er slidstærkt, så puden holder til jævnlig brug.</p>' ],
	[ 'eans' => [ '5714241007548' ], 'html' => '<p>Dipbæltet i Pro-udgave er til dig, der vil øge belastningen under dips, pull-ups og lignende øvelser. Bæltet er lavet af neopren og sidder behageligt, og den forstærkede strop er ekstremt slidstærk.</p><p>Hæng en vægtskive eller kettlebell i kæden, og du kan lægge vægt på kropsvægtsøvelserne i små trin.</p>' ],
	[ 'eans' => [ '5714241002475' ], 'html' => '<p>Double End-speedballen er et redskab for både kampsportsudøvere og fitnessentusiaster. Den hurtige, uforudsigelige bold træner reaktion, timing og hurtige slag, hvilket er vigtigt i sportsgrene som boksning og thaiboksning.</p>' ],
	[ 'eans' => [ '5714241009573' ], 'html' => '<p>Elastiksættet Pro er bygget til hjemmetræning af arme, skuldre og ryg. Det indeholder fem exertubes med en samlet modstand på 150 lbs (ca. 68,5 kg), og du kan kombinere dem for at tilpasse modstanden til øvelsen.</p><p>Elastikkerne har håndtag, så grebet bliver behageligt.</p>' ],
	[ 'eans' => [ '5714241000778' ], 'html' => '<p>Black edition-håndvægten på 6 kg er støbt i jern og har en neoprenbelægning, som giver et behageligt greb og forhindrer, at vægten glider ud af svedige hænder. Den er velegnet til aerobic og styrketræning.</p><p>Vægten sælges enkeltvis, så skal du bruge et par, lægger du to i kurven.</p>' ],
	[ 'eans' => [ '5714241000143' ], 'html' => '<p>Håndvægten Hexagon på 7 kg har et sekskantet design, så den ikke ruller væk på gulvet og er nem at stable.</p><ul><li>Robust støbejern med gummibelægning</li><li>Solidt og behageligt greb</li><li>Tåler drop og intensiv træning</li><li>Findes i vægtklasser fra 1 til 50 kg</li></ul>' ],
	[ 'eans' => [ '5714241011804' ], 'html' => '<p>Kettlebellgrebet fra Gorilla Sports gør vægtskiver til en kettlebell. Du kan lave svingende og dynamiske øvelser uden at eje en hel række faste kettlebells. Grebet er lavet til standard vægtskiver med 30 mm hul, så du skifter vægt ved at skifte skive.</p>' ],
	[ 'eans' => [ '5714241003984' ], 'html' => '<p>Det dobbelte landmine-håndtag bruges sammen med Land mine / Torsonator og giver et bredere, mere stabilt greb ved øvelser som T-bar-roning. Håndtaget placeres over vægtstangen og giver en symmetrisk håndposition.</p>' ],
	[ 'eans' => [ '5714241005797' ], 'html' => '<p>Træningsmåtten fra Nordic Strength i lilla måler 183 x 61 x 1,5 cm. Den ekstra tykkelse giver god dæmpning til gulvøvelser og mavebøjninger.</p><p>Brug den med bare fødder eller sokker, da sko kan slide på måtten.</p>' ],
	[ 'eans' => [ '5714241016144' ], 'html' => '<p>Pilates-barren kommer som komplet sæt til hjemmet med justerbare remme og seks elastikker. Den samler pilates, yoga, funktionel træning og styrketræning i ét redskab, så du kan variere øvelserne og modstanden efter behov.</p>' ],
	[ 'eans' => [ '5714241005803' ], 'html' => '<p>Pink træningsmåtte fra Nordic Strength, 183 x 61 x 1,5 cm. Tykkelsen på 1,5 cm giver god polstring og gør gulvtræningen mere behagelig.</p><p>Træn med bare fødder eller sokker, så måtten ikke slides af sko.</p>' ],
	[ 'eans' => [ '5714241004646' ], 'html' => '<p>Power Wheel er et stort mavehjul, der får flere muskelgrupper i gang på samme tid og træner kernen og den funktionelle styrke. Du kan variere øvelserne og gøre dem lettere eller sværere efter, hvor langt du ruller.</p>' ],
	[ 'eans' => [ '5714241009702' ], 'html' => '<p>Chin up-baren i sort monteres i en dørkarm og giver dig en pull-up-station til hjemmegymmet. De yderste greb lægger fokus på lats, biceps samt midterste og nedre trapezius.</p>' ],
	[ 'eans' => [ '5714241007326', '5714241000907', '5714241007333', '5714241000914' ], 'html' => '<p>Træningsbæltet er lavet af slidstærkt PU-læder og støtter ryg og kernemuskulatur under tunge løft som squats, dødløft og military press. Materialet holder længe, og bæltet fås i flere størrelser.</p>' ],
	[ 'eans' => [ '5714241004769' ], 'html' => '<p>Pull up / chin up-baren monteres på væggen og åbner for kropsvægtsøvelser, der træner styrke, udholdenhed og kropsholdning. Væggens materiale kan variere, så de medfølgende skruer passer ikke altid. Brug skruer og rawlplugs, der er egnede til netop din væg.</p>' ],
	[ 'eans' => [ '5714241009047' ], 'html' => '<p>Benlåsen er tilbehør til Semi Pro-træningsbænkene fra Marbo-Sports. Den er enkel at montere og gør det hurtigt at udvide bænken, så benene får fast støtte under øvelserne.</p>' ],
	[ 'eans' => [ '5714241005476' ], 'html' => '<p>Yogamåtten er lavet af TPE, måler 183 x 61 cm og er 10 mm tyk, så der er god plads og dæmpning til warrior-stillinger, dybe stræk og core-øvelser. Medfølgende bærestrop gør den let at tage med. Farven er sort og lilla.</p>' ],
	[ 'eans' => [ '5714241005551' ], 'html' => '<p>Triceps- og bicepsgrebet er et specialdesignet håndtag til kabelmaskiner og trænger ind på overarmenes muskler. Det er bygget i fitnesscenterkvalitet og kan bruges af både nybegyndere og erfarne.</p>' ],
	[ 'eans' => [ '5714241005773' ], 'html' => '<p>Blå træningsmåtte fra Nordic Strength, 183 x 61 x 1,5 cm. Den er til gulvøvelser, udstrækning og hjemmetræning og giver et blødt underlag.</p><p>Brug den uden sko for at undgå slid.</p>' ],
	[ 'eans' => [ '5714241006084' ], 'html' => '<p>Vægtskiven på 15 kg er lavet af hård plast til stænger med 30 mm hul. Plastskiver er et prisvenligt valg for både nybegyndere og erfarne, som vil opbygge et vægtsæt uden at bruge for mange penge.</p>' ],
	[ 'eans' => [ '5714237005978' ], 'html' => '<p>Elastiksættet med håndtag giver dig et utal af øvelser til hele kroppen derhjemme. Det er en forbedret version af en af FITNESSFREE.DKs mest solgte varer, og princippet er enkelt: jo flere elastikker du bruger, jo hårdere bliver modstanden.</p>' ],
	[ 'eans' => [ '4020676029682' ], 'html' => '<p>Eco-yogamåtten fra Trendy er lavet af TPE, der er fri for PVC, latex og skadelige kemikalier. Måtten er skridsikker, let og 6 mm tyk, og den fås i grøn. Den egner sig til yoga, pilates og hjemmetræning.</p>' ],
	[ 'eans' => [ '5714605004541' ], 'html' => '<p>Gymringene fra Peak Fitness har træringe og nylonstropper, der kan indstilles fra 150 til 280 cm. De sælges som par og bruges til gymnastik og funktionel træning, fx dips, rows og pull-ups.</p>' ],
	[ 'eans' => [ '4020676012295' ], 'html' => '<p>Den halve foam roller er lettere at holde balancen på end den hele. Den bruges til udstrækning og til at løsne spændte muskler efter træning.</p>' ],
	[ 'eans' => [ '4020676009219' ], 'html' => '<p>Medicinbolden på 2 kg har gummioverflade, der giver et godt greb. Den kan bruges til at træne mange forskellige muskelgrupper, fx med kast, rotationer og styrkeøvelser.</p>' ],
	[ 'eans' => [ '4020676003392' ], 'html' => '<p>Sort yogamåtte fra Trendy, der både kan bruges derhjemme og tages med til holdtræning. Måtten er skridsikker og let at rengøre.</p>' ],
	[ 'eans' => [ '6951376138849' ], 'html' => '<p>Skumhåndvægtene fra Aserve vejer 2 kg og leveres som par. Håndtagene er bløde, og de justerbare håndstropper gør dem velegnede til holdtræning, hvor du ikke vil tabe vægten undervejs.</p>' ],
	[ 'eans' => [ '6951376105292' ], 'html' => '<p>Agility-stigen fra Aserve er 4 meter lang og bruges til øvelser i acceleration, hastighed og koordination. Den kan lægges både ude og inde.</p>' ],
	[ 'eans' => [ '5714237006883' ], 'html' => '<p>Odin Aerobic Step er et stepbræt med skridsikker overflade og justerbar højde. Det bruges til holdtræning, både med og uden vægte, og ses ofte i forbindelse med Body Pump.</p>' ],
	[ 'eans' => [ '3701351900106' ], 'html' => '<p>Levergym Bench Connector fra Powertec kobler Utility Bench til Levergym. Den kan også bruges til at forbinde Powertec Low Row Foot Plate med Levergym.</p>' ],
	[ 'eans' => [ '3701351900014' ], 'html' => '<p>Denne connector kobler Powertec Utility Bench til Half Rack eller Power Rack. Den kan også bruges til at forbinde Powertec Low Foot Row med de to racks.</p>' ],
	[ 'eans' => [ '5703543540495' ], 'html' => '<p>Agility-stigen fra Select er 6,5 meter lang og har 13 felter, som hver måler 37 x 34 cm. Den kan forlænges ved at sætte to stiger sammen.</p><p>Stigen bruges til simpel træning, hvor intensitet og kreativitet afgør udbyttet.</p>' ],
	[ 'eans' => [ '6951376126365' ], 'html' => '<p>Håndleds- og ankelvægtene fra Aserve sidder tæt om håndled og ankler. Hvert par vejer 2 x 2 kg, og vægtene findes også i en 1 kg-version.</p>' ],
	[ 'eans' => [ '0847585007624' ], 'html' => '<p>TRX-træningsmåtten måler 120 x 60 x 1,27 cm og har behageligt skum. Den er let at tage med, så du kan lægge den, hvor du træner.</p>' ],
	[ 'eans' => [ '5714237005329' ], 'html' => '<p>Odin-træningsmåtten er 180 x 60 x 1,5 cm i sort. Tykkelsen gør den komfortabel, også efter mange mavebøjninger. Den leveres med en aftagelig transportstrop, som er let at montere.</p>' ],
	[ 'eans' => [ '5714237002861' ], 'html' => '<p>Odin Super Curl-stangen er 120 cm lang med 30 mm gribediameter og er til biceps- og tricepstræning. Curlstangen, også kaldet EZ-bar, har flere grebsmuligheder, så du kan variere øvelserne og ofte skåne leddene mere end med en lige stang.</p>' ],
	[ 'eans' => [ '5714237012877' ], 'html' => '<p>Kettlebellen på 10 kg har en jernkerne med neoprenbelægning. Den giver et komfortabelt greb og er til både hjemmetræning og professionelle træningsmiljøer.</p>' ],
	[ 'eans' => [ '5714237012778' ], 'html' => '<p>Odin-kettlebellen på 10 kg kombinerer en støbejernskerne med en vinylbelægning, som er let at rengøre. Den er til hjemmetræning og kommercielle fitnesscentre.</p>' ],
	[ 'eans' => [ '5714237016424' ], 'html' => '<p>Push-up bars i fyrretræ er 53 cm lange og tåler 150 kg. Det neutrale, ergonomiske greb aflaster håndleddene, som kan genere ved push-ups direkte på gulvet.</p>' ],
	[ 'eans' => [ '7051943747555' ], 'html' => '<p>Kettlebellen på 8 kg er støbt i jern med mat overflade, der giver et godt greb. Den er robust og egner sig til svingøvelser og styrketræning.</p>' ],
	[ 'eans' => [ '5714241018360' ], 'html' => '<p>Ankel- og håndledsvægtene vejer samlet 9 kg (2 x 4,5 kg) og øger belastningen på musklerne. De kan bruges til styrketræning, konditionstræning, opvarmning og genoptræning.</p>' ],
	[ 'eans' => [ '5714241004486' ], 'html' => '<p>Meditationspuden i sort har halvmåneform og er også kendt som en zafu. Formen er lavet til at give komfort, når du sidder i skrædder-, halv- eller hel-lotusposition under meditation og yoga.</p>' ],
	[ 'eans' => [ '5714237004230' ], 'html' => '<p>Krom-håndvægten på 5 kg er lavet i en kvalitet, der også kan bruges erhvervsmæssigt. Overfladen er slidstærk, og det nubrede håndtag giver et sikkert greb. Vægten står tydeligt på begge sider af håndvægten, og den sælges enkeltvis.</p>' ],
	[ 'eans' => [ '5714237009716' ], 'html' => '<p>Odin PRO CPU OL er en fractional plate på 2 kg til olympiske stænger. Den gør det nemt at øge modstanden i små trin og kan bruges til alle former for styrketræning, både derhjemme og i motionsrum og fitnesscentre.</p>' ],
	[ 'eans' => [ '5714237015366' ], 'html' => '<p>Den bløde kettlebell på 8 kg har en stødabsorberende overflade, som skåner både gulv og led. Den giver solid modstand til mange kettlebell-øvelser, så du kan træne intensivt uden at tage skade på hjemmet.</p>' ],
	[ 'eans' => [ '8717842038604' ], 'html' => '<p>Tunturi Platinum er massive støbejernsskiver med rustbeskyttende coating. Dette sæt rummer to skiver på 2,5 kg hver.</p><ul><li>Tynd profil med integrerede dobbeltgreb</li><li>51,5 mm boring til olympiske 50 mm stænger</li></ul>' ],
	[ 'eans' => [ '8717842038611' ], 'html' => '<p>Vægtskiven på 5 kg fra Tunturis Platinum-serie er støbt i massivt jern med rustbeskyttende coating. Den tynde profil gør, at der er plads til mange skiver på stangen, og de integrerede dobbeltgreb gør den let at løfte.</p><p>Boringen er på 51,5 mm og passer til olympiske stænger på 50 mm.</p>' ],
	[ 'eans' => [ '0885652029414' ], 'html' => '<p>Adidas-sættet kombinerer løftestropper og håndledsbeskyttere i størrelse L/XL. Stropperne er af dobbeltsidet PU med kvadratisk grebsmønster, og håndledsbeskytterne er bløde og suger sved.</p>' ],
	[ 'eans' => [ '0885652029407' ], 'html' => '<p>Løftestropper og håndledsbeskyttere i ét sæt fra Adidas, her i størrelse S/M. Stropperne har dobbeltsidet PU med kvadratisk grebsmønster, og de bløde håndledsbeskyttere optager sved under løftene.</p>' ],
	[ 'eans' => [ '0885652022774' ], 'html' => '<p>To booty bands fra Adidas i to modstandsniveauer: medium og hård. De bruges til målrettede øvelser for balder, lår og hofter og er lavet af et holdbart materiale.</p>' ],
	[ 'eans' => [ '0885652018753' ], 'html' => '<p>Tre booty bands i tekstil med tre modstandsniveauer, så du kan øge belastningen trin for trin. Tekstilen sidder stabilt og ruller ikke op, og båndene bruges til træning af ben og baller.</p>' ],
	[ 'eans' => [ '0885652021661' ], 'html' => '<p>Vægthandskerne fra Adidas vejer 0,5 kg og lægger ekstra belastning på overkroppen i løb, boksning, cardio og funktionel træning. De har fri håndflade og en komfortabel pasform.</p>' ],
	[ 'eans' => [ '7051943735910' ], 'html' => '<p>Abilica FoamRoller Pro har medium hårdhed og forskellige strukturer i overfladen. Den bruges til at løsne ømme muskler og forebygge skader.</p>' ],
	[ 'eans' => [ '5714241016786' ], 'html' => '<p>ATX Magnetic Add Weight er magnetiske ekstravægte til styrketræning. Hver vægt er på 0,5 kg og sættes på vægtstakken eller håndvægten, så du kan nå et lille skridt op i belastning, når det næste hele trin er for stort.</p>' ],
	[ 'eans' => [ '5714241001980', '5714241001997', '5714241002000', '5714241002017', '5714241002024' ], 'html' => '<p>Boksehandskerne fra Nordic Strength er sorte og røde med overflade af PU-læder, som er nem at tørre af. En justerbar velcrolukning holder dem på plads om håndleddet. Handskerne fås i størrelser fra 8 til 16 oz.</p>' ],
	[ 'eans' => [ '5714241001157' ], 'html' => '<p>Sættet har fire booty bands i polyester og latex til bentræning af baller og lår. Båndene er formet, så de ikke niver i huden, som almindelige gummielastikker kan.</p>' ],
	[ 'eans' => [ '5714241000136' ], 'html' => '<p>Hexagon-håndvægten på 6 kg har sekskantet form, som forhindrer den i at rulle, og den kan stables nemt.</p><ul><li>Robust støbejern med gummibelægning</li><li>Solidt greb</li><li>Tåler drop og intensiv træning</li></ul>' ],
	[ 'eans' => [ '5714241003434' ], 'html' => '<p>Den lille stepbænk fra Nordic Strength har to niveauer, 10 og 15 cm, så du kan skifte mellem let opvarmning og step-ups, lunges og jumps. Den er til hjemmetræning.</p>' ],
	[ 'eans' => [ '5714241000976' ], 'html' => '<p>Strength bandet i mørkeblå giver en hård modstand på 27 til 68 kg, styrke 8 af 10. Omkredsen er 208 cm, og bredden er ca. 64 mm. Det bruges til mange øvelser, fx pull-up-hjælp og styrketræning.</p>' ],
	[ 'eans' => [ '5714241011903' ], 'html' => '<p>Biceps- og tricepsgrebet fra Gorilla Sports er roterbart og bruges i træktårne og kabeltræk med gummi. Det giver mulighed for en bred vifte af armøvelser, hvor du målretter overarmens muskler.</p>' ],
	[ 'eans' => [ '5714241010241' ], 'html' => '<p>Vægtskiven på 15 kg i Basic-serien er lavet af hård plast med cementfyld og passer til stænger med 50 mm hul. Den er skånsom mod gulvet og lugtfri i forhold til gummiskiver, og kiloangivelsen er tydelig.</p>' ],
	[ 'eans' => [ '5714241005995' ], 'html' => '<p>Den gummiarmerede vægtskive på 5 kg har tre integrerede greb, som gør den nem at løfte og flytte. Den er lavet i fitnesscenterkvalitet til 50 mm stænger.</p>' ],
	[ 'eans' => [ '5714237003295' ], 'html' => '<p>Odin Crossfit PowerBand er en 6,4 cm bred træningselastik på niveau 6 med styrken X-Hard. Den kan bruges til mange øvelser, fx pull-ups med hjælp og strækøvelser.</p>' ],
	[ 'eans' => [ '5710043280561' ], 'html' => '<p>Foam rolleren i sort måler 33 cm i længden og 14 cm i diameter. Den bruges til muskelmassage og yoga og kan forbedre stabilitet og fleksibilitet.</p>' ],
	[ 'eans' => [ '5701000024427' ], 'html' => '<p>Kettlebellen på 8 kg er støbt i jern og har et farvet cover, som beskytter gulvet. Den træner hele kroppen på én gang og kræver balance, fleksibilitet og udholdenhed, og den kan bruges af både nybegyndere og erfarne.</p>' ],
