	[ 'eans' => [ '7051943733442' ], 'html' => '<p>Kettlebell på 4 kg med cover. Den bruges eksplosivt og dynamisk i en træningsform, der har hundreder af år på bagen.</p>' ],
	[ 'eans' => [ '7051943742833' ], 'html' => '<p>Håndvægten på 9 kg er i jern med grebsbelægning af neopren, som gør den behagelig at holde. Vægten sælges enkeltvis.</p>' ],
